@RestController
@RequestMapping("/api/problems")
@RequiredArgsConstructor
public class ProblemApiController {

    private final ProblemService problemService;

    @GetMapping("/{id}")
    public ResponseEntity<ProblemDto> getProblem(@PathVariable Long id) {
        return problemService.getProblemById(id)
                .map(problem -> ResponseEntity.ok(toDto(problem)))
                .orElseGet(() -> ResponseEntity.notFound().build());
    }

    private ProblemDto toDto(Problem problem) {
        return ProblemDto.builder()
                .questionerNick(problem.getQuestioner().getNick())
                .publication(problem.getPublication())
                .title(problem.getTitle())
                .question(problem.getQuestion())
                .build();
    }
}
